class Solution {
    public String gcdOfStrings(String str1, String str2) {
        int n = str1.length();
        int m = str2.length();
        int g = gcd(n, m);
        String candidate = str1.substring(0, g);
        if (repeatCheck(str1, candidate) && repeatCheck(str2, candidate)) {
            return candidate;
        }
        return "";
    }

    private int gcd(int a, int b) {
        while (b != 0) {
            int t = a % b;
            a = b;
            b = t;
        }
        return a;
    }

    private boolean repeatCheck(String s, String cand) {
        int len = cand.length();
        if (s.length() % len != 0) return false;
        for (int i = 0; i < s.length(); i += len) {
            if (!s.regionMatches(i, cand, 0, len)) return false;
        }
        return true;
    }
}

