class Solution:
    def gcdOfStrings(self, str1: str, str2: str) -> str:
        import math
        n = len(str1)
        m = len(str2)
        g = math.gcd(n, m)
        candidate = str1[:g]

        def repeatCheck(s: str, cand: str) -> bool:
            len_cand = len(cand)
            if len(s) % len_cand != 0:
                return False
            for i in range(0, len(s), len_cand):
                if s[i:i+len_cand] != cand:
                    return False
            return True

        if repeatCheck(str1, candidate) and repeatCheck(str2, candidate):
            return candidate
        return ""

