/**
 * @param {string} str1
 * @param {string} str2
 * @return {string}
 */
var gcdOfStrings = function(str1, str2) {
    const gcd = (a, b) => b === 0 ? a : gcd(b, a % b);

    const n = str1.length;
    const m = str2.length;
    const g = gcd(n, m);
    const candidate = str1.substring(0, g);

    const repeatCheck = (s, cand) => {
        const len = cand.length;
        if (s.length % len !== 0) return false;
        for (let i = 0; i < s.length; i += len) {
            if (s.substring(i, i + len) !== cand) return false;
        }
        return true;
    };

    if (repeatCheck(str1, candidate) && repeatCheck(str2, candidate)) {
        return candidate;
    }
    return "";
};
